CREATE POLICY "Users upload own claim files" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'claim-documents' AND auth.uid()::text = (storage.foldername(name))[1]);
CREATE POLICY "Users read own claim files" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'claim-documents' AND auth.uid()::text = (storage.foldername(name))[1]);
CREATE POLICY "Users delete own claim files" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'claim-documents' AND auth.uid()::text = (storage.foldername(name))[1]);